import java.util.*;

class Solution {
  public Node expTree(String s) {
    Deque<Node> operands = new ArrayDeque<>();
    Deque<Character> ops = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
      if (Character.isDigit(c)) operands.push(new Node(c));
      else if (c == '(') ops.push(c);
      else if (c == ')') {
        while (ops.peek() != '(') combine(operands, ops);
        ops.pop();
      } else {
        // left-associative: apply waiting operators of equal or higher precedence first
        while (!ops.isEmpty() && ops.peek() != '(' && prec(ops.peek()) >= prec(c)) combine(operands, ops);
        ops.push(c);
      }
    }
    while (!ops.isEmpty()) combine(operands, ops);
    return operands.pop();
  }

  private void combine(Deque<Node> operands, Deque<Character> ops) {
    Node right = operands.pop(), left = operands.pop();
    operands.push(new Node(ops.pop(), left, right));
  }

  private int prec(char op) {
    return op == '*' || op == '/' ? 2 : 1;
  }
}
